            helpCentreURL: "https://advisors.maplesure.com/help"
        };

        // Initialize configuration-dependent content
        document.getElementById('service-line-hours').textContent += portalConfig.serviceLineHours;
        document.getElementById('help-centre-link').setAttribute('href', portalConfig.helpCentreURL);

        // Form and user interaction
        document.getElementById('lookup-member').onclick = function() {
            const memberId = document.getElementById('member-id').value;
            const memberDetails = document.getElementById('member-details');
            memberDetails.textContent = mockMemberData[memberId] || 'Member not found';
